const legacyPeriods=[['friday','Sexta-feira'],['saturday_1430','Sábado · 14h30–15h30'],['saturday_post_gira','Sábado · pós-gira'],['sunday','Domingo']]
const period=(k,tasks=[])=>tasks.find(x=>x?.period_key===k&&x?.time_label)?.time_label||legacyPeriods.find(x=>x[0]===k)?.[1]||String(k||'').replace(/[_-]+/g,' ').replace(/\b\w/g,m=>m.toUpperCase())
const periodOptions=(tasks=[])=>{const seen=new Map();tasks.forEach(t=>{if(!t?.period_key)return;const k=t.period_key;if(!seen.has(k))seen.set(k,period(k,tasks))});return [...seen.entries()]}
const slugifyPeriod=s=>String(s||'').trim().toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,80)||'periodo'
const periodKeyForLabel=s=>{const n=String(s||'').trim().toLocaleLowerCase('pt-BR');const found=legacyPeriods.find(x=>x[1].toLocaleLowerCase('pt-BR')===n);return found?.[0]||slugifyPeriod(s)}
const types={gira:'Gira normal',desenvolvimento:'Desenvolvimento',interna:'Gira interna',festa:'Festa',quintal:'Quintal Ancestral',evento:'Evento do terreiro',reuniao:'Reunião',outra:'Outra atividade'}
const typeIcons={gira:'🌿',desenvolvimento:'✨',interna:'🔒',festa:'🎉',quintal:'🌳',evento:'📅',reuniao:'🤝',outra:'○'}
