 const addTask=async(turn,source=null)=>{let name=(source?.name||newTask.name).trim(),instructions=source?.instructions||newTask.instructions.trim();if(!source&&!name){name=(window.prompt('Nome da tarefa:','')||'').trim();instructions=(window.prompt('Descrição da tarefa:','')||'').trim()}if(!name){setMessage('Informe o nome da tarefa.');return}setBusy(true);try{const{data,error}=await supabase.rpc('editor_create_task',{p_gira_id:selectedId,p_name:name,p_period_key:turn.turn_key,p_slots:1,p_category_id:source?.category_id||null,p_sort_order:(tasks[turn.id]||[]).length});if(error)throw error;const taskId=data;const{error:u}=await supabase.from('tasks').update({gira_turn_id:turn.id,instructions:instructions||null,note:source?.note||null,time_label:turn.label}).eq('id',taskId);if(u)throw u;setNewTask({name:'',instructions:'',category_id:''});setLibraryOpen(false);await loadGira(selectedId)}catch(e){setMessage(err(e))}finally{setBusy(false)}};
